## 📋 코딩 스타일 가이드

```freelang
// ✅ Good - 명확한 변수명
let mut total: i32 = 0
for num in numbers {
  if num > 0 {
    total = total + num
  }
}

// ❌ Bad - 불명확한 변수명
let mut t: i32 = 0
for n in numbers {
  if n > 0 {
    t = t + n
  }
}

// ✅ Good - 적절한 들여쓰기
if condition1 {
  if condition2 {
    println("nested")
  }
}

// ✅ Good - 함수형 사용
let evens = numbers.filter(|x| x % 2 == 0)

// ❌ Bad - 불필요한 루프
let mut evens: [i32] = []
for num in numbers {
  if num % 2 == 0 {
    evens.push(num)
  }
}
```

## 🔍 자주 하는 실수

```freelang
// ❌ 무한 루프
var i: i32 = 0
while i < 10 {
  println(i)
  // i를 증가시키지 않음!
}

// ✅ 올바른 방법
var i: i32 = 0
while i < 10 {
  println(i)
  i = i + 1
}

// ❌ break/continue 혼동
for i in 1..=5 {
  if i == 3 {
    break  // ❌ 루프 전체 탈출
  }
  println(i)
}
// 출력: 1, 2

// ✅ continue 사용
for i in 1..=5 {
  if i == 3 {
    continue  // ✅ 다음 반복으로 (3은 건너뜀)
  }
  println(i)
}
// 출력: 1, 2, 4, 5

// ❌ 잘못된 범위
for i in 1..10 {
  println(i)  // 1부터 9까지 (10은 제외)
}

// ✅ 10을 포함하려면
for i in 1..=10 {
  println(i)  // 1부터 10까지
}

// ❌ 조건 실수
if x > 0 && x < 10 {
  println("0과 10 사이")
} else {
  println("범위 밖")
}

// ✅ 범위 확인
if (x > 0) && (x < 10) {
  println("0과 10 사이")
}
```

