// 이진 탐색
fn binary_search(arr: &[i32], target: i32) -> Option<usize> {
  let mut left: usize = 0
  let mut right: usize = arr.len()

  while left < right {
    let mid = (left + right) / 2
    if arr[mid] == target {
      return Some(mid)
    } else if arr[mid] < target {
      left = mid + 1
    } else {
      right = mid
    }
  }
  None
}

